package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func sumValid(tokens []string) (int, int) {
	total := 0
	invalid := 0
	for _, token := range tokens {
		n, err := strconv.Atoi(token)
		if err != nil {
			invalid++
			continue
		}
		total += n
	}
	return total, invalid
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	var tokens []string
	for scanner.Scan() {
		tokens = append(tokens, scanner.Text())
	}
	total, invalid := sumValid(tokens)
	fmt.Println(total, invalid)
}
